    b.PlayersCards.resize(2);
    if (b.GetBet() != "B3:40") return fail(3);
    b.CurrentPlayerCardsIndex = 1;
    if (b.GetBet() != "B3:80") return fail(4);
    b.CurrentPlayerCardsIndex = 2;
