struct V { float X, Y, Z; };
struct M { float E[4][3]; V Transform(const V& p) const {
    V r = { p.X * E[0][0] + p.Y * E[1][0] + p.Z * E[2][0] + E[3][0],
            p.X * E[0][1] + p.Y * E[1][1] + p.Z * E[2][1] + E[3][1],
            p.X * E[0][2] + p.Y * E[1][2] + p.Z * E[2][2] + E[3][2] }; return r; } };
