    void FrameUpdate()
    {
        ++e->actions;
        V3 cur = e->pos;
        float dx = cur.X - start.X, dy = cur.Y - start.Y, dz = cur.Z - start.Z;
        float dsq = dx * dx + dy * dy + dz * dz;
