{
    if (IS_THING_ALIVE(PCreature)) {
        PCreature->MakeNoise("SIMPLE_NOISE");
        CTCWeapon* ptc_weapon = 0;
        const CTCCarrying* ptc_carry;
        PCreature->PeekTC(&ptc_carry);
        CThing* pcarried_thing = ptc_carry->GetThingInPrimarySlot();
