    inv[3] = (f * g - d * i) / det; inv[4] = (a * i - cc * g) / det; inv[5] = (cc * d - a * f) / det;
    inv[6] = (d * h - e * g) / det; inv[7] = (b * g - a * h) / det; inv[8] = (a * e - b * d) / det;
    for (int k = 0; k < 3; ++k) inv[9 + k] = -(c[9] * inv[k] + c[10] * inv[3 + k] + c[11] * inv[6 + k]);
    for (int r = 0; r < 4; ++r)
