        target_pos.Z = PTarget->GetPos().Z;
        ptc_shot->Init(pshot_def, PCreature.Get(), 0, target_pos, (float)acc, 1.0f, 0.0f, CDefPointer<const CMeleeCombatAbilityDef>());
