struct V { float X, Y, Z; };
static float g_eps = 1e-4f;                   // DELTA_NOTIONAL_ZERO, read from memory as retail does
struct Thing { V pos; bool dead; };
struct Flourish { Thing* parent; Thing* attacker; bool cullNegX; bool cullY; };

